const b = $input.first().json.body || {};
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const mail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    const ppd = Number(b.points_per_day);
    return [{ json: {
      project_id: uuid.test(b.project_id || '') ? b.project_id : 'a0000001-0000-0000-0000-000000000001',
      start_date: /^\d{4}-\d{2}-\d{2}$/.test(b.start_date || '') ? b.start_date : null,
      points_per_day: isFinite(ppd) && ppd > 0 ? ppd : 2,
      notify_email: mail.test(b.notify_email || '') ? b.notify_email : 'htchannelas@gmail.com',
    } }];

const proj = $('Get Project').first().json;
    const inp = $('Prepare Input').first().json;
    const tasks = $input.all().map((i) => i.json).filter((t) => t.id);
    const isWeekend = (d) => d.getUTCDay() === 0 || d.getUTCDay() === 6;
    const nextWorkday = (d) => { const x = new Date(d); while (isWeekend(x)) x.setUTCDate(x.getUTCDate() + 1); return x; };
    const addWorkdays = (d, n) => {
      const x = new Date(d);
      while (n > 0) { x.setUTCDate(x.getUTCDate() + 1); if (!isWeekend(x)) n--; }
      return x;
    };
    const today = new Date(); today.setUTCHours(10, 0, 0, 0); // 17:00 giờ VN
    let start = inp.start_date ? new Date(inp.start_date + 'T10:00:00Z')
      : proj.start_date ? new Date(proj.start_date + 'T10:00:00Z') : today;
    if (start < today) start = today;
    start = nextWorkday(start);
    const deadline = new Date(proj.deadline + 'T10:00:00Z');
    const cursor = {}; // mỗi người một timeline riêng
    const schedule = [];
    for (const t of tasks) {
      const key = t.assignee_id || 'shared';
      const eff = (inp.points_per_day * (Number(t.productivity_score) || 100)) / 100;
      const days = Math.max(1, Math.ceil((Number(t.story_points) || 1) / eff));
      const begin = cursor[key] || start;
      const due = addWorkdays(begin, days - 1);
      cursor[key] = addWorkdays(due, 1);
      schedule.push({
        task_id: t.id, title: t.title, priority: t.priority, assignee: t.assignee_name || 'Chưa gán',
        days, due_date: due.toISOString(), late: due > deadline,
      });
    }
    const late = schedule.filter((s) => s.late);
    const sql = schedule.length
      ? 'UPDATE tasks t SET due_date = v.d::timestamptz, updated_at = CURRENT_TIMESTAMP FROM (VALUES ' +
        schedule.map((s) => "('" + s.task_id + "','" + s.due_date + "')").join(',') +
        ') AS v(tid,d) WHERE t.id = v.tid::uuid RETURNING t.id, t.title, t.due_date'
      : 'SELECT NULL::uuid AS id WHERE false';
    const last = schedule.reduce((m, s) => (s.due_date > m ? s.due_date : m), '');
    return [{ json: { schedule, sql, total: schedule.length, late_count: late.length, late, last_due: last, deadline: proj.deadline, project_name: proj.name } }];

const s = $('Schedule Calculation').first().json.schedule;
    const q = (x) => "'" + String(x ?? '').replace(/'/g, "''") + "'";
    const sql = s.length
      ? 'INSERT INTO activity_history (task_id,action_type,new_value,metadata) VALUES ' +
        s.map((x) => '(' + q(x.task_id) + "::uuid,'DUE_DATE_SET'," + q(x.due_date.slice(0, 10)) + ',' +
          q(JSON.stringify({ source: 'flow4_sprint_scheduling', days: x.days, late: x.late })) + '::jsonb)').join(',')
      : 'SELECT 1';
    return [{ json: { sql } }];

const d = $('Schedule Calculation').first().json;
    const prompt = 'Bạn là PM. Dự án "' + d.project_name + '" có deadline ' + d.deadline + '. ' +
      'Lịch Sprint tự động cho thấy task cuối hoàn thành ' + d.last_due.slice(0, 10) + ', ' + d.late_count + '/' + d.total + ' task trễ deadline:\n' +
      d.late.map((s) => '- ' + s.title + ' (' + s.assignee + ', due ' + s.due_date.slice(0, 10) + ')').join('\n') +
      '\n\nViết phân tích rủi ro ngắn (tối đa 120 từ, tiếng Việt, không markdown) và đề xuất 2-3 hành động khắc phục.';
    return [{ json: { prompt } }];

const d = $('Schedule Calculation').first().json;
    const email = $('Prepare Input').first().json.notify_email;
    let analysis = 'Toàn bộ task dự kiến hoàn thành trước deadline dự án. Rủi ro thấp.';
    if ($('Gemini Risk Analysis').isExecuted) {
      try { analysis = $('Gemini Risk Analysis').first().json.content.parts[0].text; } catch (e) { analysis = '(AI không trả về phân tích)'; }
    }
    const q = (s) => "'" + String(s ?? '').replace(/'/g, "''") + "'";
    const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
    const risk = d.total ? (d.late_count / d.total) * 100 : 0;
    const pid = $('Prepare Input').first().json.project_id;
    const metrics = { total_tasks: d.total, late_tasks: d.late_count, last_due: d.last_due, deadline: d.deadline };
    const sql = 'INSERT INTO reports (project_id, report_type, risk_score, ai_summary, metrics) VALUES (' + q(pid) +
      "::uuid, 'DEADLINE_RISK', " + risk.toFixed(2) + ', ' + q(analysis) + ', ' + q(JSON.stringify(metrics)) + '::jsonb) RETURNING id';
    const rows = d.schedule.map((s) => '<tr><td>' + esc(s.title) + '</td><td>' + esc(s.assignee) + '</td><td>' + s.due_date.slice(0, 10) + (s.late ? ' ⚠️' : '') + '</td></tr>').join('');
    const html = '<h2>📅 Sprint Auto-scheduling</h2><p>Dự án: <b>' + esc(d.project_name) + '</b> | Deadline: <b>' + d.deadline + '</b></p>' +
      '<p>Rủi ro trễ hạn: <b>' + risk.toFixed(0) + '%</b> (' + d.late_count + '/' + d.total + ' task)</p>' +
      '<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Task</th><th>Người làm</th><th>Due</th></tr>' + rows + '</table>' +
      '<h3>Phân tích AI</h3><p>' + esc(analysis) + '</p>';
    return [{ json: {
      sql, notify_email: email,
      subject: (d.late_count ? '⚠️' : '✅') + ' [Luồng 4] Lịch Sprint: rủi ro trễ hạn ' + risk.toFixed(0) + '%',
      html,
      response: { success: true, ...metrics, risk_score: Number(risk.toFixed(2)), ai_analysis: analysis,
        schedule: d.schedule.map((s) => ({ task: s.title, assignee: s.assignee, due_date: s.due_date, late: s.late })) },
    } }];
